import type { Ref } from "react";

interface HtmlProps {
  /** HTML produced at build time by src/lib/markdown.ts. */
  html: string;
  className?: string;
  inline?: boolean;
  id?: string;
  /** E.g. to place gap-fill inputs into the `span.blank` placeholders of the HTML. */
  ref?: Ref<HTMLDivElement>;
}

/**
 * Inserts build-time rendered Markdown. Safe: the pipeline drops raw HTML from the YAML, so
 * this only ever contains markup generated by remark/rehype, KaTeX and Shiki.
 */
export function Html({ html, className, inline = false, id, ref }: HtmlProps) {
  if (inline) {
    return (
      <span
        id={id}
        className={`md ${className ?? ""}`}
        // biome-ignore lint/security/noDangerouslySetInnerHtml: trusted build-time output (no raw HTML from content).
        dangerouslySetInnerHTML={{ __html: html }}
      />
    );
  }
  return (
    <div
      ref={ref}
      id={id}
      className={`md ${className ?? ""}`}
      // biome-ignore lint/security/noDangerouslySetInnerHtml: trusted build-time output (no raw HTML from content).
      dangerouslySetInnerHTML={{ __html: html }}
    />
  );
}
